    "ctxApiRefBody": "ctx.ref(val)              — إنشاء متغير تفاعلي\nctx.computed(fn)          — إنشاء خاصية محسوبة\nctx.watch(src, cb)        — مراقبة التغييرات\nctx.onMounted(fn)         — عند تحميل المكوّن\nctx.onUnmounted(fn)       — عند إلغاء تحميل المكوّن\n\nctx.data.client           — معلومات حساب المستخدم (تفاعلية)\nctx.data.token            — الرمز الحالي (تفاعلي)\nctx.data.isDark           — الوضع الداكن (تفاعلي)\n\nctx.api.get(path, query)  — طلب GET\nctx.api.post(path, body)  — طلب POST\nctx.api.put(path, body)   — طلب PUT\nctx.api.delete(path)      — طلب DELETE\n\nctx.formatBytes(bytes)    — تنسيق حجم الملف\nctx.formatDate(date)       — تنسيق التاريخ\nctx.copyText(text)         — النسخ إلى الحافظة\nctx.elMessage             — رسائل Element Plus\nctx.config                — إعدادات البوابة (PORTAL_CONFIG)\nctx.moduleId              — معرّف الوحدة الحالية\nctx.moduleTitle           — عنوان الوحدة الحالية",
